/**
 * Documentation and OpenAPI spec generation from blueprint contracts.
 *
 * Produces:
 * - Markdown API reference / READMEs for each node
 * - OpenAPI 3.0 YAML spec block for `api` kind nodes
 */
import { isCodeBearingNode } from './scaffold-utils.js';
// ---------------------------------------------------------------------------
// Markdown generation
// ---------------------------------------------------------------------------
const formatField = (f) => `| \`${f.name}\` | \`${f.type ?? "unknown"}\` | ${f.description ?? "—"} |`;
const formatCall = (c) => `- \`${c.target}\`${c.kind ? ` (${c.kind})` : ""}${c.description ? ` — ${c.description}` : ""}`;
/**
 * Generate a Markdown document for a single blueprint node.
 */
export const generateNodeMarkdown = (node) => {
    if (!isCodeBearingNode(node)) {
        return null;
    }
    const contract = node.contract;
    const inputs = contract?.inputs ?? [];
    const outputs = contract?.outputs ?? [];
    const attrs = contract?.attributes ?? [];
    const errors = contract?.errors ?? [];
    const calls = contract?.calls ?? [];
    const inputTable = inputs.length > 0
        ? `| Parameter | Type | Description |
|-----------|------|-------------|
${inputs.map(formatField).join("\n")}`
        : "_No inputs defined._";
    const outputTable = outputs.length > 0
        ? `| Output | Type | Description |
|--------|------|-------------|
${outputs.map(formatField).join("\n")}`
        : "_No outputs defined._";
    const attrTable = attrs.length > 0
        ? `| Attribute | Type | Description |
|-----------|------|-------------|
${attrs.map(formatField).join("\n")}`
        : "_No attributes defined._";
    const errorsList = errors.length > 0 ? errors.map((e) => `- \`${e}\``).join("\n") : "_None defined._";
    const callsList = calls.length > 0 ? calls.map(formatCall).join("\n") : "_No external calls._";
    return `# ${node.name}

${node.summary ?? "_No summary provided._"}

## Metadata

| Field | Value |
|-------|-------|
| Blueprint ID | \`${node.id}\` |
| Kind | \`${node.kind}\` |
| Language | \`${node.language ?? "typescript"}\` |
${contract?.responsibilities.length
        ? `## Responsibilities\n${contract.responsibilities.map((r) => `- ${r}`).join("\n")}\n`
        : ""}

## Inputs

${inputTable}

## Outputs

${outputTable}

## Attributes / State

${attrTable}

## Errors

${errorsList}

## External Calls

${callsList}

---
_Generated by CodeFlow Agent — do not edit manually_
`;
};
// ---------------------------------------------------------------------------
// OpenAPI 3.0 generation (api nodes only)
// ---------------------------------------------------------------------------
const openApiServer = (node) => `  servers:
    - url: http://localhost:3000
      description: Local development server`;
const openApiPath = (node) => {
    const route = node.name.replace(/\s+/g, "-").toLowerCase();
    return `  /${route}:
    post:
      operationId: ${node.id.replace(/[^a-zA-Z0-9]/g, "_")}
      summary: "${node.summary ?? node.name}"
      tags:
        - ${node.kind}
      requestBody:
        content:
          application/json:
            schema:
              type: object
              properties:
${(node.contract?.inputs ?? []).map((f) => `                ${f.name}:
                  type: ${tsTypeToOpenApi(f.type ?? "string")}`).join("\n")}
      responses:
        "200":
          description: Successful response
          content:
            application/json:
              schema:
                type: object
        "501":
          description: Scaffold not implemented
          content:
            application/json:
              schema:
                $ref: "#/components/schemas/ErrorResponse"`;
};
const tsTypeToOpenApi = (tsType) => {
    const t = tsType.toLowerCase();
    if (t === "string")
        return "string";
    if (t === "number" || t === "bigint")
        return "integer";
    if (t === "boolean")
        return "boolean";
    if (t.startsWith("array<") || t.endsWith("[]"))
        return "array";
    return "object";
};
/**
 * Generate an OpenAPI 3.0 YAML fragment for a single `api` kind node.
 * Returns null for non-api nodes.
 */
export const generateOpenApiSpec = (node) => {
    if (node.kind !== 'api') {
        return null;
    }
    return `openapi: 3.0.0
info:
  title: ${node.name}
  version: 1.0.0
paths:
  /${node.name.replace(/\s+/g, '-').toLowerCase()}:
    post:
      summary: ${node.summary ?? node.name}
      responses:
        '501':
          description: Not implemented (scaffold)
`;
};
/** Alias for generateNodeMarkdown */
export const generateNodeDocumentation = generateNodeMarkdown;
/** Alias for generateNodeMarkdown */
export const generateMarkdownDocs = generateNodeMarkdown;
